"""Render the evidence-based public acquisition report from the manifest."""
from __future__ import annotations
import pandas as pd
from common import METADATA, PROCESSED, ensure_layout

def main() -> int:
    ensure_layout()
    manifest = pd.read_csv(METADATA / "source_manifest.csv", dtype=str).fillna("")
    rows = []
    for _, x in manifest.iterrows():
        rows.append("| {canonical_name} | {source_name} | {coverage_start} | {coverage_end} | {frequency} | {n_obs} | {status} |".format(**x.to_dict()))
    panel = pd.read_csv(PROCESSED / "public_monthly_panel.csv")
    monthly = panel.drop(columns=["month"]).notna().all(axis=1).sum()
    text = """# Public-data acquisition report\n\n**Run window:** 2020-01-01 to 2026-06-30. **Main monthly panel:** 2020-01 to 2026-06 (78 rows).\n\nRaw files are immutable download responses. Processed files contain only values obtained from the recorded source; missing observations remain blank and no interpolation, forward fill, or backward fill was applied.\n\n## Acquisition manifest\n\n| variable | source | start | end | frequency | observations | status |\n|---|---|---|---|---|---:|---|\n""" + "\n".join(rows) + """\n\n## A. Successfully automated\n\n- `usd_cny`: 1,623 daily observations from 2020-01-02 through 2026-06-30. CFETS's historical query endpoint was access-controlled from this environment; the documented fallback is the Federal Reserve Economic Data `DEXCHUS` download, retained in its published CNY-per-USD direction.\n- `cpi_yoy`: 53 monthly observations, 2021-09 through 2026-06, parsed from retained official NBS release pages.\n\n## B. Partial / requires an official export\n\n- `cpi_yoy`: 2020-01 through 2021-08 remains absent from the current archive crawl and stays NA.\n\n## C. Manual or commercial-data action required\n\n- `battery_install`: request/export the China Automotive Power Battery Industry Innovation Alliance monthly release table.\n- `nev_sales`, `nev_production`: export CAAM monthly new-energy-vehicle production/sales tables.\n- `china_gov_3m`, `china_gov_6m`, `china_gov_1y`: export the actual ChinaBond tenor(s); do not replace with SHIBOR.\n- `ppi_yoy`: the NBS API returned HTTP 403 and the archive crawl did not complete its PPI pages. Export the NBS monthly producer-price series.\n- `lc_import_qty`, `lc_export_qty`: export GACC monthly HS data only after confirming the tariff definition for the candidate HS code.\n- `lc_spot`, `lc_output`, `spodumene_price`: intentionally deferred to the specified industry/commercial sources.\n\n## Required coverage answers\n\n| Question | Result |\n|---|---|\n| battery_install complete for 2020-01–2026-06? | No — official bulk endpoint unavailable. |\n| NEV complete? | No — official bulk export unavailable. |\n| USD/CNY complete? | Yes for the stated daily target range except non-publication days; 1,623 observations. |\n| 3M/6M China government yields successful? | No — marked `MANUAL_REQUIRED`; no tenor substitution. |\n| CPI/PPI complete? | No — CPI has 53 official monthly observations; PPI remains unavailable. |\n| Lithium-carbonate import/export successful? | No — GACC automated query/export unavailable; HS definition not assumed. |\n| Fully observed common monthly sample? | """ + str(monthly) + """ months. The panel still contains all 78 target months with NA preserved. |\n\n## File inventory\n\n- `data/raw/public/`: original download payloads only.\n- `data/processed/phase1/`: canonical CSV schemas and the unfilled monthly panel.\n- `data/metadata/source_manifest.csv`: source, access status, raw-file hash and coverage evidence.\n- `data/metadata/data_audit.csv`: per-variable missingness and basic-statistics audit.\n\nNo futures or options were downloaded, changed, moved, or recreated.\n"""
    (METADATA.parents[1] / "docs" / "public_data_acquisition_report.md").write_text(text, encoding="utf-8")
    print("Wrote docs/public_data_acquisition_report.md")
    return 0
if __name__ == "__main__": raise SystemExit(main())
